=== ChaosNullifier
public class ChaosNullifier : MonoBehaviour
{
	private static GameObject prefab;
	public Attack attack;
	public CircleCollider2D atkCollider;
	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.25f);
	private bool atkCompleted;
	private float forcedCooldown = 6f;
	private float destroyDelay = 1f;
	private Player currentPlayer;
	private Enemy currentEnemy;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChaosNullifier.prefab"));
	private void Start()
	{
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		atkCollider.enabled = true;
		atkStopwatch.IsRunning = true;
		UnityEngine.Object.Destroy(gameObject, destroyDelay);
		CameraController.ShakeCamera();
		PoolManager.GetPoolItem<ParticleEffect>("FloorCraterLarge").Emit(1, transform.position);
	}
	private void FixedUpdate()
	{
		if (!atkCompleted && !atkStopwatch.IsRunning)
		{
			atkCompleted = true;
			atkCollider.enabled = false;
		}
	}
	private void OnTargetHit(Entity givenEnt)
	{
		if (givenEnt == null)
		{
			return;
		}
		if (givenEnt is Enemy && !(givenEnt is Boss))
		{
			givenEnt.dotManager.AddDot(new SkillLockDotEffect(givenEnt, forcedCooldown));
			currentEnemy = givenEnt as Enemy;
			{
				foreach (Enemy.SkillState value in currentEnemy.availableEnemySkillsDict.Values)
				{
					value?.StartCooldown(forcedCooldown + UnityEngine.Random.Range(0f, 3f));
				}
				return;
			}
		}
		if (!(givenEnt is Player))
		{
			return;
		}
		givenEnt.dotManager.AddDot(new SkillLockDotEffect(givenEnt, forcedCooldown));
		currentPlayer = givenEnt as Player;
		Player.SkillState[] assignedSkills = currentPlayer.assignedSkills;
		foreach (Player.SkillState skillState in assignedSkills)
		{
			if (skillState != null && !skillState.isBasic && !skillState.isDash)
			{
				skillState.StartCooldownTimer(forcedCooldown);
			}
		}
	}
}
=== ChaosPillar
public class ChaosPillar : MonoBehaviour
{
	private static GameObject prefab;
	[HideInInspector]
	public Animator anim;
	[HideInInspector]
	public Attack attack;
	private Collider2D attackCollider;
	public int finalAttackLevel = 1;
	public float readyTime = 0.5f;
	private int readyStopwatchID = -1;
	public float attackDuration = 0.75f;
	public float hitInterval = 0.125f;
	private int hitStopwatchID = -1;
	public int maxHitCount = 6;
	private bool readyComplete;
	private bool attackComplete;
	private bool targetHit;
	private ParticleEffect chargeEffect;
	public bool useChargeEffect = true;
	private ParticleEffect blobChargeEffect;
	public bool useCastCircle = true;
	private CastingCircle castCircle;
	private ParticleSystem chaosEmitter;
	private ParticleSystem.EmissionModule chaosEmitterEmissionMod;
	public bool playFormSFX = true;
	public bool playSFXOnInterval;
	private AudioSource pillarAudio;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChaosPillar.prefab"));
	private void Awake()
	{
		anim = GetComponent<Animator>();
		Transform transform = base.transform.Find("Attack");
		this.attack = transform.GetComponent<Attack>();
		attackCollider = transform.GetComponent<Collider2D>();
		Attack attack = this.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = this.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		chaosEmitter = base.transform.Find("ChaosEmitter").GetComponent<ParticleSystem>();
		chaosEmitterEmissionMod = chaosEmitter.emission;
	}
	private void Start()
	{
		anim.Play("Ready", -1, 0f);
		readyStopwatchID = ChaosStopwatch.Begin(readyTime);
		if (useChargeEffect)
		{
			chargeEffect = PoolManager.GetPoolItem<ParticleEffect>("ChaosChargeEffect");
			ParticleEffect particleEffect = chargeEffect;
			float? emissionRate = 2f;
			Vector3? position = transform.position;
			float? playTime = readyTime * 0.5f;
			particleEffect.Play(emissionRate, position, null, playTime);
			ParticleEffect particleEffect2 = chargeEffect;
			playTime = 2f;
			position = transform.position + new Vector3(UnityEngine.Random.Range(0f, 0.25f), UnityEngine.Random.Range(0f, 0.25f), 0f);
			emissionRate = readyTime * 0.5f;
			particleEffect2.Play(playTime, position, null, emissionRate);
			ParticleEffect particleEffect3 = chargeEffect;
			emissionRate = 2f;
			position = transform.position + new Vector3(UnityEngine.Random.Range(0f, 0.25f), UnityEngine.Random.Range(0f, 0.25f), 0f);
			playTime = readyTime * 0.5f;
			particleEffect3.Play(emissionRate, position, null, playTime);
			blobChargeEffect = PoolManager.GetPoolItem<ParticleEffect>("ChaosBlobChargeEffect");
			ParticleEffect particleEffect4 = blobChargeEffect;
			playTime = 30f;
			position = transform.position;
			emissionRate = readyTime * 0.5f;
			particleEffect4.Play(playTime, position, null, emissionRate);
		}
		if (useCastCircle && readyTime > 0f)
		{
			string animName = "Draw";
			Vector3 position2 = transform.position;
			GameObject parentObj = gameObject;
			Color? color = CastingCircle.enemyColor;
			float drawTime = readyTime * 0.75f;
			castCircle = CastingCirclePool.Spawn(animName, position2, disableWithParentVal: true, parentObj, trackParentVal: true, useCastTimeVal: false, 0f, 2f, 2f, color, drawTime);
		}
		if (playFormSFX)
		{
			SoundManager.PlayAudioWithDistance("ChaosFormLong", transform.position);
		}
	}
	private void Update()
	{
		if (!readyComplete && ChaosStopwatch.Check(readyStopwatchID))
		{
			readyComplete = true;
			if (castCircle != null)
			{
				castCircle.Reset();
			}
			anim.Play("Burst", -1, 0f);
			CameraController.ShakeCamera(0.75f);
			chaosEmitterEmissionMod.enabled = true;
			chaosEmitter.Play();
			hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitInterval, Mathf.CeilToInt(attackDuration / hitInterval));
			CameraController.ShakeCamera(0.5f);
			HandleAudio();
		}
	}
	private void FixedUpdate()
	{
		if (attackComplete || !readyComplete)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
		{
		case StopwatchState.Running:
			attackCollider.enabled = false;
			break;
		case StopwatchState.Ready:
			if (targetHit && ChaosStopwatch.GetRemainingIntervals(hitStopwatchID) == 0)
			{
				attack.ChangeAttackInfoLevel(finalAttackLevel);
			}
			attackCollider.enabled = true;
			if (playSFXOnInterval)
			{
				string audioID = "ChaosStormEnd";
				Vector2? soundOrigin = transform.position;
				float standardPitchRange = SoundManager.StandardPitchRange;
				SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, standardPitchRange);
			}
			break;
		case StopwatchState.Done:
			StopAttack();
			StopChaosEmitter();
			break;
		}
	}
	private void OnTargetHit(Entity givenEnt)
	{
		if (!targetHit && !(givenEnt == null) && !(givenEnt is Destructible))
		{
			targetHit = true;
			hitStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, hitInterval, maxHitCount);
		}
	}
	public void StopAttack()
	{
		attackComplete = true;
		attackCollider.enabled = false;
		anim.Play("BurstEnd", -1, 0f);
		UnityEngine.Object.Destroy(gameObject, 1f);
		HandleAudio(status: false);
	}
	private void HandleAudio(bool status = true)
	{
		if (status)
		{
			if (pillarAudio == null || !pillarAudio.isPlaying)
			{
				pillarAudio = SoundManager.PlayAudioWithDistance("ChaosPillar", transform.position);
			}
		}
		else if (pillarAudio != null)
		{
			pillarAudio.Stop();
			pillarAudio = null;
		}
	}
	private void StopChaosEmitter()
	{
		if (!(chaosEmitter == null))
		{
			chaosEmitterEmissionMod.enabled = false;
			chaosEmitter.Stop();
		}
	}
	private void OnDestroy()
	{
		StopChaosEmitter();
	}
	public void SetSpriteLayer()
	{
		SpriteRenderer component = transform.Find("Sprite").GetComponent<SpriteRenderer>();
		component.sortingLayerName = "Effect";
		component.sortingOrder = 1;
	}
}
=== ChaosQuickStopwatch
public class ChaosQuickStopwatch
{
	private int cswID = -1;
	private float cswDelay;
	public int ID => cswID;
	public float Delay => cswDelay;
	public float TimePercentage => ChaosStopwatch.GetTimePercentage(cswID);
	public bool IsRunning
	{
		get
		{
			return !ChaosStopwatch.Check(cswID);
		}
		set
		{
			if (value)
			{
				cswID = ChaosStopwatch.Begin(cswDelay);
			}
			else
			{
				ChaosStopwatch.Stop(cswID);
			}
		}
	}
	public bool IsPaused
	{
		set
		{
			if (value)
			{
				ChaosStopwatch.Pause(cswID);
			}
			else
			{
				ChaosStopwatch.Resume(cswID);
			}
		}
	}
	public ChaosQuickStopwatch(float newDelay = 1f)
	{
		cswID = -1;
		cswDelay = newDelay;
	}
	public void SetDelay(float newDelay, bool stopCurrent = false, bool autoStart = false)
	{
		cswDelay = newDelay;
		if (stopCurrent)
		{
			IsRunning = false;
		}
		if (autoStart)
		{
			IsRunning = true;
		}
	}
	public void Refresh()
	{
		ChaosStopwatch.Refresh(cswID, cswDelay);
	}
}
=== ChaosScytheObject
public class ChaosScytheObject : MeleeAttackObject
{
	private static GameObject prefab;
	public Transform partSysTrans;
	public ParticleSystem bladeSys;
	public ParticleSystem handleSys;
	public ParticleSystem ringSys;
	private bool destroyQueued;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/ChaosScythe.prefab"));
	public override void Start()
	{
		base.Start();
		SoundManager.PlayWithDistAndSPR("ChaosWarble", transform.position);
	}
	public override void Update()
	{
		if (!destroyQueued)
		{
			base.Update();
		}
	}
	public override void EndAttack()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			bladeSys.Emit(3);
			handleSys.Emit(5);
			partSysTrans.SetParent(null);
			UnityEngine.Object.Destroy(partSysTrans.gameObject, 1f);
			SoundManager.PlayAudioWithDistance("WindThump", transform.position, null, 24f, 0.05f);
			anim.Play("Destroy", -1, 0f);
			if (base.attack != null)
			{
				Attack attack = base.attack;
				attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(CheckCollision));
			}
			if (gameObject != null)
			{
				UnityEngine.Object.Destroy(gameObject, 0.2f);
			}
		}
	}
	public void SetEmitStatus(int givenStatus)
	{
		if (givenStatus == 1)
		{
			bladeSys.Play();
			handleSys.Play();
			SoundManager.PlayWithDistAndSPR("StandardHeavySwing", transform.position);
		}
		else
		{
			bladeSys.Stop();
			handleSys.Stop();
		}
	}
	public void EmitRing()
	{
		ringSys.Emit(30);
		SoundManager.PlayWithDistAndSPR("ChaosLightningCrackle", transform.position);
	}
}
=== ChaosStopwatch
public static class ChaosStopwatch
{
	private static float currentTime;
	public static Dictionary<int, ChaosTimeValues> entries;
	private static int currentIndex;
	private static int modValue;
	private static float maxTime;
	private static List<int> removalList;
	private static int removalCount;
	private static float simDeltaTime;
	private static float upkeepVal;
	private static float minDiffVal = 0.05f;
	private static float calcDiffThreshold;
	private static float tenFrameAvgVal;
	private static float maxSpeedVal = 1.15f;
	private static float tempRemainingTime;
	public static void InitStopwatch()
	{
		entries = new Dictionary<int, ChaosTimeValues>();
		removalList = new List<int>();
		currentIndex = 0;
		modValue = 65535;
		currentTime = 0f;
		maxTime = 300f;
		upkeepVal = 0f;
		calcDiffThreshold = minDiffVal;
		tenFrameAvgVal = minDiffVal;
	}
	public static float GetSimDeltaTime(float curTime)
	{
		upkeepVal += curTime - currentTime;
		simDeltaTime = ((!(upkeepVal < calcDiffThreshold)) ? (calcDiffThreshold * maxSpeedVal) : upkeepVal);
		if (simDeltaTime > upkeepVal)
		{
			simDeltaTime = upkeepVal;
		}
		upkeepVal -= simDeltaTime;
		tenFrameAvgVal = tenFrameAvgVal * 0.9f + simDeltaTime * 0.1f;
		calcDiffThreshold = 3f * tenFrameAvgVal;
		if (calcDiffThreshold < minDiffVal)
		{
			calcDiffThreshold = minDiffVal;
		}
		return simDeltaTime;
	}
	public static void Update(float curTime)
	{
		currentTime = curTime;
		foreach (KeyValuePair<int, ChaosTimeValues> entry in entries)
		{
			if (entry.Value.paused)
			{
				if (entry.Value.endTime + maxTime < currentTime)
				{
					removalList.Add(entry.Key);
				}
			}
			else if (entry.Value.useInterval)
			{
				if (entry.Value.intervalsRemaining > 0)
				{
					if (entry.Value.endTime <= currentTime)
					{
						entry.Value.endTime += entry.Value.intervalTime;
						entry.Value.intervalsRemaining--;
						entry.Value.charges++;
					}
				}
				else if (entry.Value.charges <= 0 || entry.Value.endTime + maxTime < currentTime)
				{
					removalList.Add(entry.Key);
				}
			}
			else if (entry.Value.endTime <= currentTime)
			{
				removalList.Add(entry.Key);
			}
		}
		removalCount = removalList.Count;
		for (int i = 0; i < removalCount; i++)
		{
			entries.Remove(removalList[0]);
			removalList.RemoveAt(0);
		}
	}
	public static float GetRemainingTime(int entryID)
	{
		if (entries.ContainsKey(entryID))
		{
			return (!entries[entryID].paused) ? (entries[entryID].endTime - currentTime) : entries[entryID].pauseTime;
		}
		return 0f;
	}
	public static float GetTimePercentage(int entryID)
	{
		if (entries.ContainsKey(entryID))
		{
			if (entries[entryID].useInterval)
			{
				if (entries[entryID].intervalTime > 0f)
				{
					tempRemainingTime = GetRemainingTime(entryID);
					return (!(tempRemainingTime > entries[entryID].intervalTime)) ? (1f - tempRemainingTime / entries[entryID].intervalTime) : 0f;
				}
			}
			else if (entries[entryID].timeVal > 0f)
			{
				return 1f - GetRemainingTime(entryID) / entries[entryID].timeVal;
			}
		}
		return 1f;
	}
	public static int GetRemainingCharges(int entryID)
	{
		return entries.ContainsKey(entryID) ? entries[entryID].charges : 0;
	}
	public static int GetRemainingIntervals(int entryID)
	{
		return entries.ContainsKey(entryID) ? (entries[entryID].charges + entries[entryID].intervalsRemaining) : 0;
	}
	public static int Begin(out int stopwatchID, float timeValue, bool useInterval = false, float intervalTime = 0f, int totalIntervals = 0, int startingCharges = 0)
	{
		stopwatchID = Begin(timeValue, useInterval, intervalTime, totalIntervals, startingCharges);
		return stopwatchID;
	}
	public static int Begin(float timeValue, bool useInterval = false, float intervalTime = 0f, int totalIntervals = 0, int startingCharges = 0)
	{
		currentIndex = (currentIndex + 1) & modValue;
		if (useInterval)
		{
			if (timeValue <= 0f)
			{
				entries[currentIndex] = new ChaosTimeValues(timeValue, currentTime + intervalTime, useInterval, intervalTime, totalIntervals - 1, startingCharges + 1);
			}
			else
			{
				entries[currentIndex] = new ChaosTimeValues(timeValue, timeValue + currentTime, useInterval, intervalTime, totalIntervals, startingCharges);
			}
		}
		else
		{
			entries[currentIndex] = new ChaosTimeValues(timeValue, timeValue + currentTime);
		}
		return currentIndex;
	}
	public static bool Check(int entryID)
	{
		return !entries.ContainsKey(entryID);
	}
	public static StopwatchState CheckInterval(int entryID, bool getCharge = true)
	{
		if (entries.ContainsKey(entryID))
		{
			if (getCharge && entries[entryID].charges > 0)
			{
				entries[entryID].charges--;
				return StopwatchState.Ready;
			}
			if (entries[entryID].charges > 0 || entries[entryID].intervalsRemaining > 0)
			{
				return StopwatchState.Running;
			}
		}
		return StopwatchState.Done;
	}
	public static bool IntervalIsActive(int entryID)
	{
		return entries.ContainsKey(entryID) && (entries[entryID].charges > 0 || entries[entryID].intervalsRemaining > 0);
	}
	public static void AddToRemaingTime(int entryID, float additionalTimeValue, bool updateIntervalTime = false)
	{
		if (entries.ContainsKey(entryID))
		{
			entries[entryID].endTime += additionalTimeValue;
			if (updateIntervalTime && entries[entryID].useInterval)
			{
				entries[entryID].intervalTime += additionalTimeValue;
			}
		}
		else if (!updateIntervalTime)
		{
			entries[entryID] = new ChaosTimeValues(additionalTimeValue, currentTime + additionalTimeValue);
		}
	}
	public static void Refresh(int entryID, float timeValue)
	{
		if (entries.ContainsKey(entryID))
		{
			entries[entryID].endTime = currentTime + timeValue + ((!entries[entryID].useInterval) ? 0f : entries[entryID].intervalTime);
		}
		else
		{
			entries[entryID] = new ChaosTimeValues(timeValue, currentTime + timeValue);
		}
	}
	public static void RefreshIntervals(int entryID, int newIntervalsRemaining)
	{
		if (entries.ContainsKey(entryID) && entries[entryID].useInterval)
		{
			entries[entryID].intervalsRemaining = newIntervalsRemaining - entries[entryID].charges;
		}
	}
	public static void IncrementRemainingIntervals(int entryID, int incrementCount = 0)
	{
		if (entries.ContainsKey(entryID) && entries[entryID].useInterval)
		{
			entries[entryID].intervalsRemaining += ((incrementCount <= 0) ? 1 : incrementCount);
		}
	}
	public static void ReduceTimeRemaining(int entryID, float timeReduction)
	{
		if (entries.ContainsKey(entryID))
		{
			entries[entryID].endTime -= timeReduction;
		}
	}
	public static void SetIntervalTime(int entryID, float newIntervalTime)
	{
		if (entries.ContainsKey(entryID) && entries[entryID].useInterval)
		{
			entries[entryID].intervalTime = newIntervalTime;
		}
	}
